create extension if not exists pgcrypto;
create table public.assets (id text primary key, name text not null, category text not null check (category in ('metal','index','crypto')), color text not null, tv_symbol text not null, feed_source text not null, feed_symbol text not null, currency text not null default 'USD');
create table public.prices (asset_id text primary key references public.assets(id), price numeric not null, change_24h_pct numeric, change_7d_pct numeric, updated_at timestamptz not null default now());
create table public.macro_signals (id uuid primary key default gen_random_uuid(), asset_id text not null references public.assets(id), score int not null check(score between 0 and 100), rating text not null check(rating in ('bullish','neutral','bearish')), bullish int not null default 0, neutral int not null default 0, bearish int not null default 0, upside_pct numeric, current_pct numeric, downside_pct numeric, upside_price numeric, downside_price numeric, factors jsonb not null default '{}'::jsonb, investment_horizon text check(investment_horizon in ('3m','6-12m','1y+')), ai_narrative text, computed_at timestamptz not null default now());
create index macro_signals_asset_computed_idx on public.macro_signals(asset_id, computed_at desc);
create table public.news (id uuid primary key default gen_random_uuid(), asset_id text not null references public.assets(id), title text not null, source text, source_url text, url text not null unique, category text, sentiment text check(sentiment in ('bullish','neutral','bearish')), ai_summary text, published_at timestamptz, fetched_at timestamptz not null default now());
create index news_asset_published_idx on public.news(asset_id, published_at desc);
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, archetype text, display_currency text not null default 'USD', display_unit text not null default 'oz', language text not null default 'fr', plan text not null default 'free' check(plan in ('free','pro')), telegram_chat_id text, discord_webhook_url text, created_at timestamptz not null default now());
create table public.lots (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, asset_id text not null references public.assets(id), type text not null check(type in ('physical','paper','spot','futures')), quantity numeric not null check(quantity > 0), unit text not null, cost numeric not null, currency text not null default 'USD', buy_date date, premium numeric not null default 0, dealer text, note text, created_at timestamptz not null default now());
create index lots_user_asset_idx on public.lots(user_id, asset_id);
create table public.alerts (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, asset_id text not null references public.assets(id), trigger_type text not null check(trigger_type in ('price_above','price_below','score_change','news_keyword')), trigger_value jsonb not null, channels text[] not null check(cardinality(channels) > 0), active boolean not null default true, last_triggered_at timestamptz, cooldown_minutes int not null default 60 check(cooldown_minutes >= 0), created_at timestamptz not null default now());
create table public.alert_history (id uuid primary key default gen_random_uuid(), alert_id uuid not null references public.alerts(id) on delete cascade, triggered_at timestamptz not null default now(), payload jsonb, channels_success text[] not null default '{}', channels_failed text[] not null default '{}');
